PEOPLE="CREATE TABLE people(id INTEGER PRIMARY KEY,name TEXT,age INTEGER,city TEXT,phone TEXT); INSERT INTO people VALUES(1,'Ada',20,'Moscow','123'),(2,'Boris',30,'Moscow',NULL),(3,'Vera',20,'Kazan','');"
SALES="CREATE TABLE sales(id INTEGER PRIMARY KEY,category TEXT,amount INTEGER,cancelled INTEGER); INSERT INTO sales VALUES(1,'tea',40,0),(2,'tea',70,0),(3,'milk',20,0),(4,'tea',999,1);"
CLIENTS="CREATE TABLE clients(id INTEGER PRIMARY KEY,name TEXT); CREATE TABLE orders(id INTEGER PRIMARY KEY,client_id INTEGER,amount INTEGER); INSERT INTO clients VALUES(1,'Ada'),(2,'Boris'); INSERT INTO orders VALUES(1,1,10),(2,1,20);"
def build(add):
 def s(keys,idea,code,out,trace,try_it,setup=PEOPLE,langs=('sql',)):
  for lang in langs:add(lang,keys,idea,code,out,trace,try_it,setup=setup)
 def both(*args,**kw):s(*args,**kw,langs=('sql','postgresql'))
 s('first-values','База данных хранит записи. Таблица похожа на лист с колонками: одна строка — один человек, столбцы — имя и возраст. SQL — способ попросить базу показать или изменить данные. SELECT переводится как «выбери». Для первого вычисления таблица вообще не нужна.',
 'SELECT 3 + 4 AS answer;',[[7]],'SELECT просит вернуть результат выражения справа.|3 + 4 вычисляется в число 7. AS answer задаёт заголовок столбца.|Точка с запятой завершает запрос. Внизу появится таблица: один столбец answer и одна строка со значением 7.','Замените + на *. Сколько строк останется в результате и какое число будет внутри?',setup='')
 s('columns select','Запрос на чтение не стирает и не переставляет исходные записи. SELECT задаёт нужные столбцы, FROM — таблицу, из которой читаем. ORDER BY определяет порядок результата. Названия колонок пишут без кавычек вокруг обычного имени; текстовые значения — в одинарных кавычках.',
 'SELECT name, age\nFROM people\nORDER BY id;', [['Ada',20],['Boris',30],['Vera',20]],'FROM people означает «возьми строки из people». Исходные данные доступны ниже примера.|SELECT name, age оставляет два столбца и именно в таком порядке.|ORDER BY id выдаёт сначала запись 1, затем 2 и 3. Без него порядок не обещан.','Оставьте после SELECT только name. Изменится количество строк или количество столбцов?')
 s('aliases','AS даёт результату понятное имя. Это ярлык над столбцом ответа, а не переименование исходной таблицы. Выражение age + 2 считается отдельно для каждой выбранной строки. WHERE оставляет только подходящие строки.',
 'SELECT name, age + 2 AS later\nFROM people\nWHERE id = 1;', [['Ada',22]],'WHERE id = 1 оставляет Ada: её исходный возраст 20.|В ответе считаем 20 + 2 и получаем 22.|Над вторым столбцом написано later. В самой таблице age по-прежнему 20.','Замените + 2 на + 5 и имя later на future_age. Что изменяет каждое из этих исправлений?')
 s('where','WHERE — фильтр, как пропускной пункт: каждая строка проходит проверку. В результате остаются только строки, у которых условие истинно. >= включает границу; > исключает равное значение. Фильтр влияет на строки, а список SELECT — на столбцы.',
 'SELECT name\nFROM people\nWHERE age > 20\nORDER BY id;', [['Boris']],'Проверяем Ada: 20 > 20 ложно, строка не проходит.|У Boris 30 > 20 истинно; у Vera снова 20, она не проходит.|Из оставшейся строки выводим только name. Возраст использован для проверки, но не обязан быть в ответе.','Измените > на >=. Какие два человека добавятся и почему?')
 s('operators','AND значит «выполнены оба требования», OR — «выполнено хотя бы одно». Например, «из Москвы и младше 25» строже, чем «из Москвы или младше 25». При смешивании условий используйте скобки, чтобы явно показать, какие проверки объединяются.',
 "SELECT name FROM people\nWHERE city = 'Moscow' AND age < 25\nORDER BY id;",[['Ada']],'Ada подходит по городу и возрасту.|Boris из нужного города, но ему 30: AND его не пропускает.|Vera моложе 25, но из другого города. Она тоже не проходит.','Замените AND на OR. Объясните для каждого человека, какое из требований теперь его пропускает.')
 s('null','NULL обозначает отсутствующее или неизвестное значение. Это не ноль и не пустая строка. В таблице телефон Boris неизвестен, а у Vera записан пустой текст. Для отсутствия значения используют IS NULL, а не = NULL.',
 'SELECT name FROM people\nWHERE phone IS NULL\nORDER BY id;', [['Boris']],'Проверяем именно отсутствие значения в phone.|У Boris NULL, поэтому строка подходит. У Vera есть строка длиной ноль — это другое значение.|IS NOT NULL делает обратную проверку: оставляет заполненные значением ячейки, включая пустую строку.','Что вернёт условие phone = \'\'? Почему оно не выберет Boris?')
 s('like','LIKE сравнивает текст с шаблоном. Знак % обозначает любое количество символов, даже ноль; _ — ровно один символ. Шаблон тоже текст, поэтому заключён в одинарные кавычки. Это не обычное сравнение на полное равенство.',
 "SELECT name FROM people WHERE name LIKE 'V%' ORDER BY id;",[['Vera']],'V задаёт обязательную первую букву.|% разрешает любой остаток имени, поэтому Vera подходит.|Ada и Boris не начинаются с V. Для точного имени использовали бы name = \'Vera\'.','Замените шаблон на \'%a\'. Какие имена оканчиваются на a? Не путайте начало и конец шаблона.')
 s('in','IN проверяет, входит ли значение в перечисленный набор. Это короткая запись нескольких равенств, соединённых OR. Для поиска двух конкретных записей удобнее набор их id, а не диапазон между ними.',
 'SELECT name FROM people WHERE id IN (1, 3) ORDER BY id;', [['Ada'],['Vera']],'Для каждой строки сравниваем id с 1 и 3.|id = 2 не входит в набор, поэтому Boris исключён.|ORDER BY по-прежнему нужен: порядок чисел в IN сам по себе не сортирует результат.','Поменяйте набор на (3, 1). Изменится ли порядок при сохранённом ORDER BY id?')
 s('between','BETWEEN выбирает диапазон вместе с обеими границами. Для чисел age BETWEEN 20 AND 25 означает age >= 20 AND age <= 25. Нижняя граница должна быть слева, верхняя справа.',
 'SELECT name, age FROM people WHERE age BETWEEN 20 AND 25 ORDER BY id;', [['Ada',20],['Vera',20]],'Ada и Vera находятся прямо на нижней границе 20. Она включена, поэтому обе строки подходят.|Boris с возрастом 30 выше верхней границы и не попадает в результат.|SELECT сохраняет имя и возраст, чтобы можно было увидеть причину отбора.','Измените верхнюю границу на 30. Кто добавится? Что будет при нижней границе 21?')
 s('distinct','DISTINCT удаляет одинаковые строки из ответа. Исходные записи при этом остаются. Если выбрать только город, два человека из Москвы дадут одинаковое значение, которое можно показать один раз. Если выбрать город вместе с именем, строки уже будут разными.',
 'SELECT DISTINCT city FROM people ORDER BY city;', [['Kazan'],['Moscow']],'До удаления повторов получаются Moscow, Moscow, Kazan.|DISTINCT оставляет два разных значения.|ORDER BY city располагает их по порядку текста: Kazan, затем Moscow.','Добавьте name в SELECT. Почему DISTINCT теперь не оставит только два результата?')
 s('limit','ORDER BY задаёт сортировку, LIMIT — сколько первых строк после неё вернуть. DESC означает убывание, ASC — возрастание. При одинаковом основном значении полезен второй ключ, иначе порядок равных строк не определён.',
 'SELECT name, age FROM people ORDER BY age DESC, id ASC LIMIT 2;', [['Boris',30],['Ada',20]],'Сначала располагаем людей по возрасту: 30, затем два значения 20.|Равные возраста упорядочиваем по id: Ada раньше Vera.|LIMIT 2 оставляет только Boris и Ada. Сначала ограничить случайные строки и потом сортировать было бы другой задачей.','Измените DESC на ASC. Кто станет первым и почему нужен второй ключ id?')
 s('count','COUNT(*) считает строки целиком. COUNT(column) считает только строки, где этот столбец не NULL. Пустой текст считается значением. Поэтому число людей и число известных телефонов могут отличаться.',
 'SELECT COUNT(*) AS people_count, COUNT(phone) AS phone_count FROM people;', [[3,2]],'В people три строки, значит COUNT(*) = 3.|Только phone у Boris равен NULL. Две другие ячейки считаются, включая пустой текст Vera.|Результат содержит одну строку с итогами, а не отдельную строку для каждого человека.','Какая из двух величин изменится, если телефон Vera тоже станет NULL?')
 s('sum','SUM складывает значения столбца у выбранных строк. Сначала мысленно примените фильтр, затем складывайте только оставшиеся числа. Без GROUP BY такой запрос даёт один общий итог.',
 "SELECT SUM(age) AS total FROM people WHERE city = 'Moscow';", [[50]],'Фильтр оставляет Ada и Boris.|Их возраста 20 и 30. Складываем: 50.|SUM не считает людей. Для количества нужен COUNT. Если подходящих значений вообще нет, SUM возвращает NULL.','Уберите WHERE. Какое число добавится к сумме?')
 s('average','MIN находит наименьшее значение, MAX — наибольшее, AVG — среднее арифметическое. Среднее получается из суммы, поделённой на количество непустых значений. Разные агрегаты можно получить в одной строке ответа.',
 "SELECT MIN(age), MAX(age), AVG(age) FROM people WHERE city = 'Moscow';", [[20,30,25]],'У выбранных людей два возраста: 20 и 30.|Минимум 20, максимум 30.|Среднее равно (20 + 30) / 2 = 25. Порядок столбцов соответствует порядку функций в SELECT.','Оставьте только Ada условием id = 1. Чему будут равны все три показателя?')
 s('group','GROUP BY собирает записи в группы по одинаковому значению. Это как разложить чеки по городам и отдельно посчитать каждый набор. После группировки строка ответа представляет группу, а не одного исходного человека.',
 'SELECT city, COUNT(*) AS n FROM people GROUP BY city ORDER BY city;', [['Kazan',1],['Moscow',2]],'Сначала получаются две группы: Kazan с Vera и Moscow с Ada и Boris.|COUNT(*) вычисляется отдельно внутри каждой группы.|Выводим название группы и её размер. name без группировки или агрегата здесь не описывает группу однозначно.','Замените COUNT(*) на SUM(age). Что теперь будет означать число напротив города?')
 s('insert','INSERT добавляет новую запись. Список столбцов и список значений читаются попарно: первое значение идёт в первый столбец. Остальные строки сохраняются. Уникальный id должен отличаться от уже существующих.',
 "INSERT INTO people(id,name,age,city,phone) VALUES(4,'Max',18,'Kazan',NULL);\nSELECT name,age FROM people WHERE id=4;", [['Max',18]],'В INSERT перечислены пять столбцов и пять соответствующих значений.|NULL означает, что телефон пока неизвестен.|Второй запрос читает добавленную запись, чтобы мы увидели результат изменения.','Поменяйте возраст новой записи. Что произойдёт, если повторно добавить тот же id без сброса базы?')
 s('update','UPDATE исправляет существующие строки. SET задаёт новое значение, WHERE ограничивает, кому его присвоить. Без WHERE изменение затронет все строки таблицы. Полезная привычка: сначала проверить тот же фильтр через SELECT.',
 'UPDATE people SET age=21 WHERE id=1;\nSELECT name,age FROM people ORDER BY id;', [['Ada',21],['Boris',30],['Vera',20]],'WHERE id=1 выбирает только Ada.|SET age=21 заменяет её возраст, не создавая нового человека.|Контрольный SELECT показывает: два остальных возраста не изменились.','Какой фильтр понадобится, чтобы изменить только Vera? Не убирайте WHERE для этой задачи.')
 s('delete','DELETE удаляет записи, а не отдельные значения внутри них. WHERE определяет, какие строки исчезнут. DELETE без WHERE оставляет пустую таблицу. В учебном примере изменения изолированы; в настоящей базе перед удалением обязательно проверяют выбранные строки.',
 'DELETE FROM people WHERE id=2;\nSELECT name FROM people ORDER BY id;', [['Ada'],['Vera']],'Фильтр находит запись Boris.|DELETE удаляет всю эту строку, включая возраст, город и телефон.|Таблица и её столбцы продолжают существовать. Два остальных человека остались.','Как отличить задачу «удалить человека» от «убрать его телефон»? Для второй нужен UPDATE, а не DELETE.')
 s('create types','CREATE TABLE описывает новую таблицу. У каждого столбца есть имя и тип значения. INTEGER — целое число, REAL — дробное, TEXT — текст. PRIMARY KEY делает столбец уникальным идентификатором строки. NOT NULL запрещает отсутствие значения.',
 "CREATE TABLE notes(id INTEGER PRIMARY KEY, title TEXT NOT NULL);\nINSERT INTO notes(id,title) VALUES(1,'Купить чай');\nSELECT id,title FROM notes;", [[1,'Купить чай']],'Первая команда задаёт структуру, но ещё не добавляет ни одной записи.|INSERT создаёт одну строку: id = 1, title = Купить чай.|SELECT показывает её. Одинаковый id второй раз использовать нельзя. В SQLite обычные типы гибче, чем в PostgreSQL; объявление типа не заменяет все проверки.','Попробуйте отдельным запуском вставить NULL в title. Какое правило таблицы остановит это действие?',setup='')
 s('constraints','Ограничения защищают таблицу от неподходящих данных, даже если запрос написан с ошибкой. UNIQUE не допускает повтор, NOT NULL запрещает отсутствие, CHECK проверяет логическое условие. Эти правила задают при создании таблицы.',
 "CREATE TABLE items(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,price INTEGER NOT NULL CHECK(price>=0));\nINSERT INTO items VALUES(1,'Tea',10);\nSELECT name,price FROM items;", [['Tea',10]],'id идентифицирует товар, name обязателен и не повторяется.|price тоже обязателен. CHECK разрешает ноль и положительные цены, но не отрицательные.|Правильная запись проходит все правила и появляется в результате.','По очереди попробуйте цену -1, NULL и повторное имя Tea с другим id. Какое ограничение сработает в каждом случае?',setup='')
 s('join','JOIN соединяет строки из двух таблиц по условию ON. Представьте список заказов с номером клиента и отдельный справочник клиентов с именами. Номер позволяет найти нужное имя. Короткие имена c и o — псевдонимы таблиц, чтобы было видно, откуда берётся столбец.',
 'SELECT c.name,o.amount\nFROM clients AS c\nJOIN orders AS o ON o.client_id=c.id\nORDER BY o.id;', [['Ada',10],['Ada',20]],'У Ada id=1. Обе строки orders содержат client_id=1, поэтому обе получают имя Ada.|JOIN выдаёт по строке на каждую найденную пару. Имя может повторяться, это не случайный дубль.|У Boris нет пары в orders, поэтому INNER JOIN его не показывает.','Почему результат содержит две строки Ada, хотя в clients она записана один раз?',setup=CLIENTS)
 s('subquery','Подзапрос — вычисление, результат которого нужен другому запросу. Например, сначала найдём средний возраст, затем сравним с ним каждого человека. Внутренний SELECT помещается в круглые скобки. Здесь он возвращает ровно одно число.',
 'SELECT name FROM people\nWHERE age > (SELECT AVG(age) FROM people)\nORDER BY id;', [['Boris']],'Внутренний запрос получает (20 + 30 + 20) / 3, примерно 23.33.|Внешний сравнивает 20, 30 и 20 с этим порогом.|Только 30 больше среднего. Порог не записан вручную и пересчитается при изменении данных.','Что поменяется, если вместо AVG взять MIN? Посчитайте результат сначала на исходных трёх возрастах.')
 both('left-join','LEFT JOIN сохраняет каждую строку слева, даже когда справа нет пары. Для клиента без заказов столбцы заказа будут NULL. Поэтому COUNT(o.id) даёт ноль заказов, а COUNT(*) ошибочно посчитал бы сохранённую строку как один заказ.',
 'SELECT c.name,COUNT(o.id) AS n\nFROM clients c LEFT JOIN orders o ON o.client_id=c.id\nGROUP BY c.id,c.name ORDER BY c.name;', [['Ada',2],['Boris',0]],'Слева клиенты, справа их заказы. Ada получает две пары, Boris — строку с пустой правой частью.|Группируем по клиенту, чтобы снова получить одну строку на человека.|Считаем только непустые id заказов: 2 и 0.','Замените COUNT(o.id) на COUNT(*). Объясните, почему число у Boris изменилось.',setup=CLIENTS)
 both('case','CASE выбирает значение по условию прямо внутри запроса. Это SQL-вариант «если — иначе». WHEN задаёт проверку, THEN — результат при успехе, ELSE — запасной результат, END завершает выражение. Первая подходящая ветка побеждает.',
 "SELECT name,CASE WHEN age>=25 THEN 'older' ELSE 'younger' END AS label\nFROM people ORDER BY id;", [['Ada','younger'],['Boris','older'],['Vera','younger']],'Для Ada проверка age>=25 ложна, берём younger.|Для Boris истинна, берём older.|Слово AS label именует вычисленный столбец. Для NULL в задании нужна отдельная проверка IS NULL перед обычными сравнениями.','Поставьте границу 20. Какие строки сменят метку?')
 both('coalesce','COALESCE берёт первое значение, которое не NULL. Это способ показать запасную подпись при отсутствующих данных. Пустая строка не NULL, поэтому она не будет автоматически заменена. Такой выбор зависит от того, что именно вы считаете «нет данных».',
 "SELECT name,COALESCE(phone,'нет номера') AS contact FROM people ORDER BY id;", [['Ada','123'],['Boris','нет номера'],['Vera','']],'Телефон Ada заполнен: возвращается 123.|У Boris NULL, поэтому выбираем запасной текст.|У Vera пустая строка, но не NULL. Она остаётся пустой; не подменяем разные случаи без требования задачи.','Чем результат отличается от замены сразу всех пустых и неизвестных телефонов?')
 both('exists','EXISTS отвечает только на вопрос «найдена хотя бы одна строка?». Сами найденные данные выводить не нужно. NOT EXISTS выбирает обратный случай — отсутствие связанной записи. Внутренний запрос может ссылаться на текущего клиента внешнего запроса.',
 'SELECT c.name FROM clients c\nWHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.client_id=c.id)\nORDER BY c.name;', [['Boris']],'Для Ada внутренний запрос находит заказы. EXISTS истинно, NOT EXISTS ложно — Ada не выбирается.|Для Boris ничего не найдено, поэтому NOT EXISTS истинно.|SELECT 1 внутри — условное значение: важен факт наличия строки, а не её содержимое.','Уберите NOT. Как изменится смысл вопроса к базе?',setup=CLIENTS)
 both('having','WHERE отбирает отдельные записи до расчёта итогов. HAVING отбирает уже готовые группы после расчёта. Например, сначала убираем отменённые покупки, затем складываем продажи по категориям, и только потом выбираем категории с большим итогом.',
 'SELECT category,SUM(amount) AS total FROM sales\nWHERE cancelled=0 GROUP BY category\nHAVING SUM(amount)>=100 ORDER BY category;', [['tea',110]],'WHERE убирает отменённые 999: эта сумма не должна участвовать.|У tea остаются 40 + 70 = 110, у milk 20.|HAVING оставляет только итог не меньше 100. Нельзя фильтровать ещё не рассчитанную сумму обычным WHERE.','Уберите WHERE и посчитайте новый итог tea. Почему это будет неверный отчёт по неотменённым продажам?',setup=SALES)
 both('transaction','Транзакция объединяет несколько изменений в одно целое. При переводе денег списание и зачисление должны произойти вместе. BEGIN начинает группу, COMMIT подтверждает, ROLLBACK отменяет незавершённую группу. Транзакция не проверяет баланс сама: такие проверки надо написать отдельно.',
 'BEGIN;\nUPDATE accounts SET balance=balance-10 WHERE id=1;\nUPDATE accounts SET balance=balance+10 WHERE id=2;\nCOMMIT;\nSELECT id,balance FROM accounts ORDER BY id;', [[1,90],[2,30]],'В начале на счетах 100 и 20.|После двух UPDATE получаются 90 и 30: общая сумма остаётся 120.|COMMIT сохраняет обе операции. При отмене через ROLLBACK вернулись бы 100 и 20.','Замените COMMIT на ROLLBACK. Предскажите оба баланса перед запуском.',setup='CREATE TABLE accounts(id INTEGER PRIMARY KEY,balance INTEGER); INSERT INTO accounts VALUES(1,100),(2,20);')
 both('savepoint','SAVEPOINT ставит закладку внутри транзакции. ROLLBACK TO возвращает состояние к этой закладке, сохраняя более раннюю работу. Это похоже на отмену последних шагов, когда весь документ выбрасывать не нужно.',
 "BEGIN;\nINSERT INTO log VALUES('keep');\nSAVEPOINT mark;\nINSERT INTO log VALUES('undo');\nROLLBACK TO mark;\nCOMMIT;\nSELECT text FROM log;", [['keep']],'Сначала добавляем keep — это происходит до закладки.|После mark добавляем undo.|Откат к mark убирает только undo. COMMIT подтверждает оставшийся keep.','Перенесите SAVEPOINT выше первого INSERT. Каких записей не останется после отката?',setup='CREATE TABLE log(text TEXT);')
 both('recursive','Дерево папок хранит для каждой папки id родителя. Чтобы найти все вложенные папки, одного JOIN мало: глубина заранее неизвестна. Рекурсивный CTE начинает с корня и повторяет поиск детей найденных узлов. Нужно понимать условие остановки и не создавать циклические связи.',
 'WITH RECURSIVE tree(id,depth) AS (\n SELECT id,0 FROM folders WHERE id=1\n UNION ALL\n SELECT f.id,t.depth+1 FROM folders f JOIN tree t ON f.parent_id=t.id\n) SELECT id,depth FROM tree ORDER BY id;', [[1,0],[2,1],[3,2]],'Первая часть находит корень 1 и даёт глубину 0.|Повторяющаяся часть находит ребёнка 2, затем ребёнка 3; на каждом шаге глубина увеличивается.|Когда новых детей нет, повторение заканчивается. На данных с циклом нужна дополнительная защита.','Добавьте папку (4,1) в исходные данные. Какую глубину она получит?',setup='CREATE TABLE folders(id INTEGER PRIMARY KEY,parent_id INTEGER); INSERT INTO folders VALUES(1,NULL),(2,1),(3,2);')
 both('running-total','Оконная функция считает по соседним строкам, не сворачивая их в одну группу. Накопленная сумма — итог «от начала до этой строки». ORDER BY внутри OVER определяет порядок расчёта; внешний ORDER BY — порядок показа.',
 'SELECT id,SUM(amount) OVER(ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS total\nFROM moves ORDER BY id;', [[1,10],[2,7],[3,12]],'Первая строка: сумма только 10.|Вторая: 10 + (-3) = 7. Третья: 10 - 3 + 5 = 12.|ROWS ... задаёт окно от первой до текущей строки. Каждое движение остаётся в ответе.','Измените второе движение с -3 на -5. Какие итоги поменяются, а какой останется прежним?',setup='CREATE TABLE moves(id INTEGER PRIMARY KEY,amount INTEGER); INSERT INTO moves VALUES(1,10),(2,-3),(3,5);')
 both('view','VIEW — сохранённое имя для запроса. Оно удобно, когда один и тот же отбор нужен в разных местах. Обычное представление не является отдельной копией данных: при чтении оно обращается к текущим строкам исходной таблицы.',
 'CREATE VIEW young AS SELECT name,age FROM people WHERE age<25;\nSELECT name FROM young ORDER BY name;', [['Ada'],['Vera']],'Сохраняем запрос под именем young.|Читаем young так же, как таблицу. Получаем людей моложе 25.|Если исходные возраста изменятся, обычное VIEW покажет новый результат без специального обновления.','Измените возраст Ada на 26 до последнего SELECT. Почему она исчезнет из young?')
 both('upsert','UPSERT решает две ситуации: если записи нет — добавить; если уникальный ключ уже существует — обновить. ON CONFLICT указывает ключ конфликта. excluded обозначает предложенную новую строку, а имя таблицы — уже сохранённую.',
 "INSERT INTO stock(name,qty) VALUES('tea',3)\nON CONFLICT(name) DO UPDATE SET qty=stock.qty+excluded.qty;\nSELECT name,qty FROM stock;", [['tea',5]],'В stock уже есть tea с количеством 2.|Новая вставка tea,3 сталкивается с уникальным ключом name.|Вместо ошибки выполняем обновление: 2 + 3 = 5. Простое qty=excluded.qty заменило бы количество на 3.','Поменяйте новое имя на milk. Какая ветка сработает теперь?',setup="CREATE TABLE stock(name TEXT PRIMARY KEY,qty INTEGER); INSERT INTO stock VALUES('tea',2);")
 both('normalization','Связь таблиц позволяет хранить имя клиента один раз, а в заказах — только его id. Внешний ключ REFERENCES требует, чтобы указанный клиент существовал. NOT NULL запрещает заказ вообще без клиента. Это два разных правила, и часто нужны оба.',
 'CREATE TABLE purchases(id INTEGER PRIMARY KEY,client_id INTEGER NOT NULL REFERENCES clients(id));\nINSERT INTO purchases VALUES(10,1);\nSELECT p.id,c.name FROM purchases p JOIN clients c ON c.id=p.client_id;', [[10,'Ada']],'В clients уже есть Ada с id=1.|Новая таблица purchases хранит номер заказа и ссылку на клиента.|По ссылке находим имя. Изменение имени клиента не требует переписывать каждый его заказ.','Попробуйте client_id=999. Почему такая запись должна быть отклонена?',setup="CREATE TABLE clients(id INTEGER PRIMARY KEY,name TEXT); INSERT INTO clients VALUES(1,'Ada');")
 s('index','Индекс похож на указатель в книге: помогает найти подходящие записи без просмотра каждой страницы. Он занимает место и требует обновления при изменении данных. Для маленькой таблицы база может обоснованно выбрать полный просмотр — наличие индекса не гарантирует его использование.',
 'CREATE INDEX idx_people_age ON people(age);\nSELECT name FROM people WHERE age=30;', [['Boris']],'Создаём отдельную структуру поиска по age.|Сам SELECT по смыслу не меняется и должен вернуть тот же результат.|В SQLite EXPLAIN QUERY PLAN перед SELECT покажет выбранный способ поиска. Сравнивайте план, а не только наличие индекса.','Добавьте EXPLAIN QUERY PLAN перед SELECT. Найдите в плане название созданного индекса или объяснение полного просмотра.')
 s('trigger','Триггер — действие базы, которое автоматически запускается при определённом изменении. AFTER INSERT означает «после вставки». NEW содержит значения только что добавленной строки. Такой механизм подходит для журнала, но скрытые действия надо хорошо документировать.',
 "CREATE TRIGGER remember AFTER INSERT ON notes BEGIN INSERT INTO audit(text) VALUES(NEW.text); END;\nINSERT INTO notes(text) VALUES('чай');\nSELECT text FROM audit;", [['чай']],'Создаём правило remember; само его создание ещё не добавляет журнал.|Вставляем чай в notes.|База выполняет триггер и копирует NEW.text в audit. Ручного второго INSERT в пользовательском коде нет.','Добавьте ещё одну заметку. Сколько записей появится в audit?',setup='CREATE TABLE notes(text TEXT); CREATE TABLE audit(text TEXT);')
 s('migration','Миграция — изменение структуры уже существующей базы без удаления нужных данных. ALTER TABLE ADD COLUMN добавляет столбец. DEFAULT определяет значение по умолчанию, поэтому старые строки получают осмысленное начальное состояние.',
 'ALTER TABLE tasks ADD COLUMN done INTEGER NOT NULL DEFAULT 0;\nUPDATE tasks SET done=1 WHERE id=1;\nSELECT id,title,done FROM tasks ORDER BY id;', [[1,'Tea',1],[2,'Milk',0]],'До изменения у задач есть только id и title.|Добавляем done с начальным значением 0; старые названия не исчезают.|Первую задачу отмечаем как выполненную. Вторая остаётся с 0.','Почему пересоздание пустой таблицы вместо ALTER потеряло бы задачи?',setup="CREATE TABLE tasks(id INTEGER PRIMARY KEY,title TEXT); INSERT INTO tasks VALUES(1,'Tea'),(2,'Milk');")
 both('capstone','Сначала определите, что означает одна строка каждой таблицы. Клиент может иметь несколько заказов, заказ — несколько позиций. После JOIN количество строк растёт. Если сложить уже готовую сумму заказа на уровне его позиций, она повторится несколько раз. Считайте стоимость именно qty * price каждой позиции.',
 'SELECT c.name,COALESCE(SUM(o.amount),0) AS total\nFROM clients c LEFT JOIN orders o ON o.client_id=c.id\nGROUP BY c.id,c.name ORDER BY c.name;', [['Ada',30],['Boris',0]],'Маленький пример пока считает готовые суммы заказов: у Ada 10 + 20 = 30.|Boris сохраняется благодаря LEFT JOIN. Его SUM равен NULL, COALESCE превращает его в 0.|В большой задаче замените простую сумму на сумму стоимостей позиций и проверьте, не повторилась ли одна покупка.','Нарисуйте две строки Ada после JOIN. Почему SUM(DISTINCT amount) не является универсальным исправлением двойного подсчёта?',setup=CLIENTS)
 s('first','PostgreSQL — программа для хранения таблиц и выполнения SQL-запросов. Начнём без предположения, что вы уже знаете SQLite. Строка таблицы здесь — один человек; name и age — столбцы. SELECT выбирает столбцы, FROM называет таблицу, WHERE проверяет каждую строку, ORDER BY задаёт порядок ответа.',
 'SELECT name,age FROM people WHERE age>=25 ORDER BY id;', [['Boris',30]],'В исходных данных три человека с возрастами 20, 30 и 20.|WHERE age>=25 оставляет только возраст 30.|SELECT показывает имя и возраст этой строки. ORDER BY делает порядок явным; в большей выборке это важно.','Сначала уберите WHERE целиком и посмотрите все три записи. Затем верните условие с границей 20.',langs=('postgresql',))
 s('boolean','BOOLEAN хранит именно истину или ложь: TRUE и FALSE. Например, active отвечает на вопрос «активен ли человек?». Это отдельный тип, а не договорённость хранить 0 и 1. Неизвестное значение NULL также возможно, если столбец его допускает.',
 'SELECT name FROM members WHERE active IS TRUE ORDER BY id;', [['Ada']],'В members у Ada TRUE, у Boris FALSE.|IS TRUE выбирает только достоверно истинные значения.|FALSE и NULL не подходят. Строка \'true\' и ключевое слово TRUE — разные записи в SQL.','Поменяйте условие на active IS FALSE. Чьё имя появится?',setup="CREATE TABLE members(id INTEGER,name TEXT,active BOOLEAN); INSERT INTO members VALUES(1,'Ada',TRUE),(2,'Boris',FALSE);",langs=('postgresql',))
 s('casts','Тип определяет, какие операции доступны значению. Текст \'12\' и число 12 могут выглядеть одинаково, но выполняют разные роли. PostgreSQL поддерживает ::type для явного преобразования. Стандартная запись CAST(value AS type) делает то же самое.',
 "SELECT '12'::integer + 3 AS total;", [[15]],'Сначала строка \'12\' преобразуется в целое число 12.|К полученному числу прибавляется 3.|Получаем 15. Текст \'abc\' не получится преобразовать таким способом: нужна обработка неверных данных.','Замените ::integer на CAST(\'12\' AS integer), сохранив сложение. Совпадут ли результаты?',setup='',langs=('postgresql',))
 s('ilike','ILIKE ищет текст по шаблону без различия регистра букв. Это удобно для пользовательского поиска: человек может набрать маленькую a вместо большой A. % по-прежнему обозначает любой остаток строки. На правила сравнения сложных алфавитов влияет настройка базы.',
 "SELECT name FROM people WHERE name ILIKE 'a%' ORDER BY id;", [['Ada']],'Шаблон начинается с маленькой a.|ILIKE разрешает соответствующую большую A, поэтому Ada подходит.|Остальные имена начинаются с других букв. Это отличие от обычного регистрозависимого LIKE в PostgreSQL.','Сравните ILIKE и LIKE на том же шаблоне. Почему SQLite LIKE нельзя считать точной копией PostgreSQL LIKE?',langs=('postgresql',))
 s('returning','RETURNING позволяет сразу получить значения изменённой строки. Это удобно после INSERT: не нужно отдельным запросом угадывать, какую запись только что добавили. RETURNING не отменяет вставку — запись остаётся в таблице.',
 "INSERT INTO people(id,name,age) VALUES(4,'Max',18) RETURNING id,name;", [[4,'Max']],'INSERT создаёт нового человека.|RETURNING id,name формирует ответ именно из добавленной строки.|Порядок столбцов ответа задаётся после RETURNING так же, как после SELECT.','Добавьте age в RETURNING. Изменится ли сама вставляемая запись?',langs=('postgresql',))
 s('json jsonb-path','JSONB хранит структурированный документ внутри одной ячейки. -> достаёт поле как JSON, ->> — как текст. Для вложенного поля нужно пройти уровни по очереди. Если затем нужно числовое сравнение, текст следует явно превратить в число.',
 "SELECT ('{\"stock\":{\"count\":3}}'::jsonb -> 'stock' ->> 'count')::integer + 1;", [[4]],'::jsonb превращает исходный текст в документ.|-> \'stock\' достаёт вложенный объект; ->> \'count\' достаёт текст 3.|::integer превращает его в число, после чего прибавление 1 даёт 4.','Уберите + 1 и замените его на >= 2. Что теперь будет описывать результат?',setup='',langs=('postgresql',))
 s('cte','WITH позволяет дать промежуточному запросу имя и затем читать его как таблицу внутри одного SQL-выражения. Это помогает разбить длинную задачу на понятные этапы. CTE здесь не сохраняет новую постоянную таблицу в базе.',
 'WITH young AS (SELECT name FROM people WHERE age<25)\nSELECT name FROM young ORDER BY name;', [['Ada'],['Vera']],'В скобках отбираем людей моложе 25.|Даём этому промежуточному результату имя young.|Внешний SELECT читает young и сортирует имена. Следующий отдельный запрос не увидит этот CTE.','Измените фильтр внутри WITH. Почему наружный запрос можно оставить прежним?',langs=('postgresql',))
 s('window','ROW_NUMBER присваивает номер каждой строке, не объединяя строки в группы. OVER описывает порядок нумерации. Если значения равны, нужен дополнительный ключ, чтобы номера не менялись случайно. Нумерация результата не переписывает id в таблице.',
 'SELECT name,ROW_NUMBER() OVER(ORDER BY age DESC,id) AS place FROM people ORDER BY place;', [['Boris',1],['Ada',2],['Vera',3]],'По возрасту первым идёт Boris: получает 1.|У Ada и Vera возраст одинаковый, поэтому решает id.|Внешний ORDER BY place показывает строки в порядке новых номеров.','Смените age DESC на age ASC. Кто получит номер 1?',langs=('postgresql',))
 s('arrays','Массив хранит несколько значений одного типа в одной ячейке. ANY проверяет равенство хотя бы одному элементу массива. Это удобно для маленького набора тегов. Для сложных связей и отдельных свойств тегов часто лучше отдельная таблица.',
 "SELECT 'sql' = ANY(ARRAY['python','sql']) AS found;", [[True]],'ARRAY[...] создаёт массив двух текстовых значений.|Сравниваем sql с каждым элементом.|Одно сравнение истинно, поэтому итог TRUE. ANY не требует совпадения со всеми элементами.','Замените sql слева на c. Какой результат ожидается?',setup='',langs=('postgresql',))
 s('date','Дата — отдельный тип данных. Прибавляя дни к дате, база сама учитывает длины месяцев и високосные годы. Склеивание текстов не умеет этого делать. Сначала получаем дату, затем выполняем арифметику, а для предсказуемого вывода можем преобразовать результат в текст.',
 "SELECT (DATE '2024-02-28' + 2)::text;", [['2024-03-01']],'DATE задаёт тип значения 2024-02-28.|В 2024 году есть 29 февраля: это первый добавленный день.|Второй день — 1 марта. ::text делает результат явно текстовым.','Попробуйте тот же расчёт для 2023 года. Почему ответ отличается?',setup='',langs=('postgresql',))
 s('partial-index','Частичный индекс содержит только строки, подходящие под его условие. Например, открытые обращения интересуют чаще закрытых. Такой индекс меньше полного, но помогает лишь запросам, совместимым с его фильтром. Нужность оценивают по данным и плану выполнения.',
 'CREATE INDEX idx_active ON members(id) WHERE active IS TRUE;\nSELECT name FROM members WHERE active IS TRUE ORDER BY id;', [['Ada']],'В индекс включены только активные записи.|Фильтр запроса совпадает с условием индекса.|На двух строках оптимизатор может предпочесть обычный просмотр. Это не ошибка создания индекса.','Поставьте EXPLAIN перед SELECT. Почему результат запроса должен быть тем же даже без использования индекса?',setup="CREATE TABLE members(id INTEGER,name TEXT,active BOOLEAN); INSERT INTO members VALUES(1,'Ada',TRUE),(2,'Boris',FALSE);",langs=('postgresql',))
 s('function','SQL-функция получает аргументы и возвращает значение. Типы аргументов и результата — её договор с вызывающим кодом. LANGUAGE SQL означает, что тело написано как SQL-запрос. $$ ограничивают текст тела, чтобы внутри не пришлось экранировать каждую кавычку.',
 'CREATE FUNCTION plus_two(n integer) RETURNS integer LANGUAGE SQL AS $$ SELECT n+2 $$;\nSELECT plus_two(5);', [[7]],'Определяем имя plus_two и один целочисленный параметр n.|Тело выбирает n+2, а RETURNS integer обещает целый результат.|Вызов plus_two(5) подставляет 5 и получает 7. Для процентов обратите внимание на целочисленное деление.','Вызовите plus_two(-2). Почему тело функции менять не нужно?',setup='',langs=('postgresql',))
 s('materialized','Материализованное представление хранит результат запроса как снимок. Это может ускорять чтение сложного отчёта, но снимок устаревает при изменении исходных данных. REFRESH MATERIALIZED VIEW пересчитывает его. Обычное VIEW работает иначе: отдельный снимок оно не хранит.',
 'CREATE MATERIALIZED VIEW summary AS SELECT SUM(amount) AS total FROM payments;\nINSERT INTO payments VALUES(5);\nREFRESH MATERIALIZED VIEW summary;\nSELECT total FROM summary;', [[15]],'Изначально payments содержит 10, поэтому первый снимок равен 10.|После INSERT в исходной таблице уже 10 и 5, но старый снимок ещё 10.|REFRESH пересчитывает сумму, и SELECT возвращает 15.','Уберите REFRESH. Какой устаревший результат вы увидите и почему?',setup='CREATE TABLE payments(amount INTEGER); INSERT INTO payments VALUES(10);',langs=('postgresql',))
